INSERT INTO videos (category, title, content_type, genre, language, year, stream_url, download_url, thumb, description, created_at) VALUES ('outframe', 'Dhurandhar: The Revenge Official Hindi - Out Of The Frame 3D Trailer', 'Trailer', 'Action', 'Hindi', 2026, 'https://files.ani3d.in/0:/outframe/web/Dhurandhar%20The%20Revenge%20Hindi%20-%20Out%20Of%20The%20Frame%203D%20Trailer.mp4?inline=true', 'https://files.ani3d.in/0:/outframe/web/Dhurandhar%20The%20Revenge%20Hindi%20-%20Out%20Of%20The%20Frame%203D%20Trailer.mp4', 'https://i.ibb.co/yms1CKFd/Dhurandhar-The-Revenge-Official-Hindi-Out-Of-The-Frame-3-D.png', 'Out of Frame 3D is 2D content that mimics a 3D visual style where selected elements extend beyond the frame or black screen area to create a pop-out effect. It brings specific elements forward to deliver a 3D-like experience without the need for glasses or special devices.

This video was edited by Aniket Bhosale in Adobe Premiere Pro using masking tools to isolate elements and build layered depth.

The intent is to make 2D content feel more 3D and immersive.', '2026-06-20T11:17:44.500124+00:00');
